CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE tournaments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, venue text NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, timezone text NOT NULL DEFAULT 'America/Mexico_City', status text NOT NULL DEFAULT 'registration' CHECK(status IN ('registration','competition','archived')), auto_approve boolean NOT NULL DEFAULT false, registration_open boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_on >= starts_on));
CREATE UNIQUE INDEX one_active_tournament ON tournaments(organization_id) WHERE status <> 'archived';
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','registration','scheduling','referee','viewer')), active boolean NOT NULL DEFAULT true);
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, tournament_id uuid NOT NULL REFERENCES tournaments, name text NOT NULL, capacity integer NOT NULL DEFAULT 16 CHECK(capacity BETWEEN 4 AND 256), group_size integer NOT NULL DEFAULT 4 CHECK(group_size BETWEEN 3 AND 8), qualifiers integer NOT NULL DEFAULT 2 CHECK(qualifiers BETWEEN 1 AND 4), duration_minutes integer NOT NULL DEFAULT 60 CHECK(duration_minutes BETWEEN 15 AND 240), rest_minutes integer NOT NULL DEFAULT 30 CHECK(rest_minutes BETWEEN 0 AND 240), rules jsonb NOT NULL DEFAULT '{"sets":3,"games":6,"superTiebreak":true,"goldenPoint":true}', draw_seed text, draw_published boolean NOT NULL DEFAULT false, UNIQUE(tournament_id,name));
CREATE TABLE teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, tournament_id uuid NOT NULL REFERENCES tournaments, category_id uuid NOT NULL REFERENCES categories, name text NOT NULL, players jsonb NOT NULL CHECK(jsonb_array_length(players)=2), captain integer NOT NULL CHECK(captain IN (0,1)), email text NOT NULL, phone text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'verification' CHECK(status IN ('verification','pending','approved','rejected','withdrawn')), verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tournament_id,email));
CREATE TABLE sessions (token_hash text PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, user_id uuid REFERENCES users, team_id uuid REFERENCES teams, expires_at timestamptz NOT NULL, CHECK((user_id IS NULL) <> (team_id IS NULL)));
CREATE TABLE verification_tokens (token_hash text PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, team_id uuid NOT NULL REFERENCES teams, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, category_id uuid NOT NULL REFERENCES categories, name text NOT NULL, UNIQUE(category_id,name));
CREATE TABLE group_members (organization_id uuid NOT NULL REFERENCES organizations, group_id uuid NOT NULL REFERENCES groups ON DELETE CASCADE, team_id uuid NOT NULL REFERENCES teams, PRIMARY KEY(group_id,team_id));
CREATE TABLE courts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, tournament_id uuid NOT NULL REFERENCES tournaments, name text NOT NULL, opens_at text NOT NULL DEFAULT '08:00', closes_at text NOT NULL DEFAULT '22:00', enabled boolean NOT NULL DEFAULT true, UNIQUE(tournament_id,name));
CREATE TABLE matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, tournament_id uuid NOT NULL REFERENCES tournaments, category_id uuid NOT NULL REFERENCES categories, group_id uuid REFERENCES groups ON DELETE CASCADE, stage text NOT NULL DEFAULT 'group' CHECK(stage IN ('group','knockout')), round integer NOT NULL DEFAULT 1, position integer NOT NULL DEFAULT 0, home_id uuid REFERENCES teams, away_id uuid REFERENCES teams, court_id uuid REFERENCES courts, starts_at timestamptz, ends_at timestamptz, status text NOT NULL DEFAULT 'unscheduled' CHECK(status IN ('unscheduled','scheduled','live','pending','disputed','finished','suspended')), score jsonb, winner_id uuid REFERENCES teams, finish_reason text, real_started_at timestamptz, real_ended_at timestamptz, CHECK(home_id IS NULL OR away_id IS NULL OR home_id <> away_id), CHECK((starts_at IS NULL AND ends_at IS NULL AND court_id IS NULL) OR (starts_at IS NOT NULL AND ends_at > starts_at AND court_id IS NOT NULL)));
CREATE INDEX matches_schedule ON matches(tournament_id,starts_at,court_id);
CREATE INDEX matches_category ON matches(category_id,status);
CREATE TABLE result_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, match_id uuid NOT NULL REFERENCES matches ON DELETE CASCADE, team_id uuid REFERENCES teams, user_id uuid REFERENCES users, score jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE change_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, team_id uuid NOT NULL REFERENCES teams, kind text NOT NULL, before_value jsonb NOT NULL, after_value jsonb NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','applied','rejected','failed')), resolved_by uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sponsor_levels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, tournament_id uuid NOT NULL REFERENCES tournaments, name text NOT NULL, amount numeric NOT NULL DEFAULT 0 CHECK(amount>=0), benefits text NOT NULL DEFAULT '', zones text[] NOT NULL DEFAULT '{portal}', priority integer NOT NULL DEFAULT 1, logo_size integer NOT NULL DEFAULT 120 CHECK(logo_size BETWEEN 40 AND 400));
CREATE TABLE sponsors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, tournament_id uuid NOT NULL REFERENCES tournaments, level_id uuid REFERENCES sponsor_levels, name text NOT NULL, website text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', logo_url text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'prospect' CHECK(status IN ('prospect','reviewed','negotiation','won','lost','excluded')), notes text NOT NULL DEFAULT '', evidence jsonb NOT NULL DEFAULT '[]', affinity integer NOT NULL DEFAULT 0 CHECK(affinity BETWEEN 0 AND 100), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, sponsor_id uuid NOT NULL REFERENCES sponsors, subject text NOT NULL, body text NOT NULL, channel text NOT NULL DEFAULT 'manual' CHECK(channel IN ('manual','gmail')), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','queued','sending','sent','failed','cancelled')), approved_by uuid REFERENCES users, approved_at timestamptz, sent_at timestamptz, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oauth_connections (organization_id uuid PRIMARY KEY REFERENCES organizations, encrypted_tokens text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oauth_states (state_hash text PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE audit_events (id bigserial PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, actor text NOT NULL, action text NOT NULL, resource_id text, before_value jsonb, after_value jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_organization ON audit_events(organization_id,created_at DESC);
CREATE TABLE idempotency_keys (organization_id uuid NOT NULL REFERENCES organizations, actor text NOT NULL, key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,actor,key));
CREATE TABLE schedule_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, tournament_id uuid NOT NULL REFERENCES tournaments, actor text NOT NULL, before_value jsonb NOT NULL, after_value jsonb NOT NULL, undone boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
